module SIRTest

import ..Main: h1, h2

@info h1("SIR with soft proposals")

using Test
using BenchmarkTools
using Random: seed!
using PhyloPOMP
import PartiallyObservedMarkovProcesses as POMP

heavy = occursin(r"y|yes|t|true", get(ENV,"RUN_HEAVY_TESTS","no"))

"""
   A soft filter for SIR with steady-state demography and waning of
   immunity. Both destructive and non-destructive sampling are
   permitted.
"""
const mgp = @mgp_soft_filter(
    name=SIR,
    demes=(Infec,), deme_occupancy=(I,),
    state=(S,I,R), enns=(n,), ells=(ℓ,),
    knowledge = function(v; deme, type, time)
        demekron!(v, Infec)
        true
    end,
    jumps=(
        trans=(
            rate=β*S*I/pop, popmove=(S -= 1; I += 1),
            moves=(
                reg=(
                    type=id,
                    pi=1-ℓ*(ℓ-1)/n/(n+1),
                    boost=@binomratio(n,ℓ,2,0)+ℓ*@binomratio(n,ℓ,2,1),
                ),
                fork=(
                    type=fork,
                    from=Infec, to=(Infec,Infec),
                    boost=@binomratio(n,ℓ,2,2),
                ),
            ),
        ),
        recov=(
            rate=γ*I, popmove=(I -= 1; R += 1),
            moves=(
                regular=(
                    type=id,
                    pi=@indicator(n>ℓ, 1-ℓ/n),
                ),
            ),
        ),
        wane=(
            rate=ω*R, popmove=(R -= 1; S += 1),
            moves=(reg=(type=id,),)),
        sample=(
            rate=ψ*I,
            moves=(
                inline=(
                    type=chop, signature=(1,1),
                    from=Infec, to=Infec,
                    boost=@binomratio(n,ℓ,1,1),
                ),
                terminal=(
                    type=chop, signature=(1,0), from=Infec,
                    boost=@binomratio(n,ℓ,1,0),
                ),
            ),
        ),
        dsample=(
            rate=χ*I, popmove=(I -= 1; R += 1),
            moves=(
                terminal=(
                    type=chop, signature=(1,0), from=Infec,
                    boost=1.0,
                ),
            ),
        ),
    ),
    rinit = function(; S0, I0, R0, pop, _...)
        barycentric(Int64,(S=S0,I=I0,R=R0),pop)
    end,
    init_state = :(S=Int64(0),I=Int64(0),R=Int64(0)),
)

