@testset verbose=true "LBDP with soft proposals" begin

    seed!(2123986527)

    @test mgp isa Module
    tr = parse_newick(n, time=3)
    g = @guide mgp tr fsmarkov(Infec=>1)

    p = filter_pomp(mgp, g; params=map(Float64,(;β=16,γ=2,ω=0,ψ=0,χ=1,pop=5000,S0=30,I0=0.1,R0=70)))
    @test p isa POMP.PompObject
    pfilter(p,Np=100)

    @info h2("pfilter benchmark")
    @btime pfilter($p, Np=1000)

    if heavy

        @time pf = [pfilter(p, Np=1000) for _ ∈ 1:16]
        est,se = logmeanexp(logLik.(pf), se=true)

        trans = @with coef(p) begin
            m = inv(S0+I0+R0)
            λ = β*S0*m
            μ = γ
            n0 = round(m*I0*pop)
            (;λ,μ,ψ,χ,n0)
        end

        ll,_ = lbdp_exact(tr; trans...)

        @info "filter: $(round(est,digits=1)) ± $(round(2se,digits=2))"

    end

end

end
